	writeAuditLine(t, brainDir, `{"action":"bundle_import","generated_at":"2026-10-10T10:00:00Z"}`)
	writeAuditLine(t, brainDir, `{"action":"bundle_import","generated_at":"2026-10-11T10:00:00Z"}`)

